document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,a="info"){return`\n      <div class="insight-card ${a}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const a=document.getElementById("flower-shop-form"),t=document.getElementById("flower-shop-result");a&&a.addEventListener("submit",function(a){a.preventDefault();const i=parseInt(document.getElementById("shop-area").value),o=parseFloat(document.getElementById("equipment-cost").value),r=parseFloat(document.getElementById("refrigeration-cost").value),l=parseFloat(document.getElementById("initial-inventory").value),d=parseFloat(document.getElementById("avg-ticket").value),c=parseInt(document.getElementById("daily-customers").value),p=parseFloat(document.getElementById("peak-multiplier").value),v=parseInt(document.getElementById("peak-days").value),u=parseFloat(document.getElementById("rent").value),g=parseFloat(document.getElementById("cogs-percentage").value),m=parseFloat(document.getElementById("staff-costs").value),f=parseFloat(document.getElementById("other-expenses").value);if(i<=0||d<=0||c<=0)return t.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const y=o+r+l,w=30-v,$=c*d,h=c*p*d,b=$*w,k=h*v,I=b+k,E=12*I,F=.08*E,B=E+F,P=B/12,S=I*g/100,x=S+(u+m+f),D=12*x,M=B-D,R=M/12,A=M/B*100,L=y/M,C=M/y*100,O=B/i,T=I/30;let q="info";M<0?q="warning":A>30&&(q="success");let U="info";C<20?U="warning":C>40&&(U="success"),t.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🌸 Flower Shop Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n(y),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(R),`Margin: ${e(A)}`,q)}\n            ${s("⏱️ Payback Period",`${L.toFixed(1)} years`,`ROI: ${e(C)}`,L<=3?"success":"warning")}\n            ${s("🛍️ Average Daily Revenue",n(T),"Per day","info")}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Equipment & renovation</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Refrigeration equipment</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Initial inventory</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(y)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Monthly Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Regular days (${w} days × $${$.toFixed(0)})</span>\n                  <span>${n(b)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Peak days (${v} days × $${h.toFixed(0)})</span>\n                  <span>${n(k)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Additional services (delivery, arrangements)</span>\n                  <span>${n(F/12)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Revenue</strong></span>\n                  <span><strong>${n(P)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Cost of goods sold (${g}% of revenue)</span>\n                  <span>${n(S)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Rent</span>\n                  <span>${n(u)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Staff (florist, sales)</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Utilities & other expenses</span>\n                  <span>${n(f)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(x)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>📏 Space Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per sq ft: <strong>${n(O)}/year</strong><br>\n                Shop area: <strong>${i} sq ft</strong><br>\n                Average transaction: <strong>${n(d)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${M>0?"success":"warning"}">\n              <h6>📊 Seasonal Analysis</h6>\n              <div class="metric-subtitle">\n                Regular day: <strong>${n($)}</strong><br>\n                Peak day: <strong>${n(h)}</strong><br>\n                Peak multiplier: <strong>${p.toFixed(1)}x</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${R>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(M)}</strong><br>\n                Weekly profit: <strong>${n(M/52)}</strong><br>\n                Daily profit: <strong>${n(M/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Operational Metrics</h6>\n              <div class="metric-subtitle">\n                Daily customers: <strong>${c} people</strong><br>\n                Peak days/month: <strong>${v} days</strong><br>\n                Gross margin: <strong>${e(100-g)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${A<25?"<li>⚠️ Low profitability. Consider reducing COGS percentage or increasing prices.</li>":""}\n              ${d<20?"<li>💰 Low average transaction. Promote add-on products and premium arrangements.</li>":""}\n              ${L>3?"<li>⏰ Long payback period. Optimize startup costs or increase foot traffic.</li>":""}\n              ${p<3?"<li>📈 Low peak multiplier. Market more aggressively for holidays and events.</li>":""}\n              ${A>35?"<li>🎉 Excellent profitability! Consider opening additional locations.</li>":""}\n              <li>🌹 Specialize in wedding floristry to increase average transaction value.</li>\n              <li>📱 Develop online ordering and delivery service to expand customer base.</li>\n              <li>🎨 Offer floral design workshops as additional revenue stream.</li>\n              <li>🤝 Partner with wedding planners, event venues, and funeral homes.</li>\n              <li>📊 Track inventory waste closely and optimize purchasing patterns.</li>\n              <li>⭐ Create signature arrangements to differentiate from competitors.</li>\n              <li>🎁 Add complementary products: vases, cards, small gifts, plants.</li>\n              <li>📅 Plan inventory carefully for seasonal peaks and valleys.</li>\n              <li>🌐 Build strong social media presence with beautiful floral photography.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.flowerShopBusinessData={"Shop Area (sq ft)":i,"Total Investment ($)":y,"Annual Revenue ($)":B,"Annual Expenses ($)":D,"Annual Profit ($)":M,"Monthly Profit ($)":R,"Profit Margin (%)":A,"Annual ROI (%)":C,"Payback Period (years)":L,"Average Transaction ($)":d,"Daily Customers":c,"Revenue per sq ft ($)":O}}),window.downloadCSV=function(){if(!window.flowerShopBusinessData)return;const n=Object.entries(window.flowerShopBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="flower-shop-business-plan.csv",s.click()}});